# ---------------------------------------------------------------- 대피선
prop rail_stop 29 4
text 24 5 "대피선. 레일 한 줄이 짧게 갈라져 벽에서 끝난다. 차막이에 운반조 분필 '마주 오면 두 번 — 여기로'." w=2
# ---------------------------------------------------------------- 신길 무너진 승강장(1호선 환승 통로는 흙에 막힘)
text 45 3 "신길역 승강장 안내판. '신길 → 여의도 방면 대피소 만원. 다음 대피소: 여의나루(대심도)'. 판 아래 번호표가 흩어져 있다 — 0393, 0394…" w=2
prop queue_rail 48 5
prop queue_rail 54 5
prop queue_rail 60 5
prop queue_skel 51 4
prop queue_skel2 55 3
prop queue_skel3 62 4
prop rubble 64 3
prop rubble2 65 4
text 55 5 "줄 선 채 잠든 사람들." w=4 scene=U04_SINGIL
text 64 5 "1호선 환승 통로. 흙과 철근이 천장까지 차올랐다. 틈으로 마른 바람이 샌다." w=2 scene=U04_DIG
# ---------------------------------------------------------------- 측실(운반조 중계)
prop locker_rent_lt 70 3
box 70 3 locker w=2 name="운반조 중계 사물함" claim=760,1115 th=2 cond="U04_RUN >= 3"
text 72 5 "운반조 측실. 벽에 분필 '중계 — 반장 허락 받은 사람만'. 바닥에 젖은 수레 바퀴 자국." w=2 scene=U04_RELAY
prop crate_o 73 3
box 73 3 u04_relay name="측실 궤짝"
# ---------------------------------------------------------------- 내리막(여의도 방면)
prop chalk_h 90 6
prop chalk_h 96 6
prop chalk_h 102 6
text 92 6 "벽 분필 '↘ 여의도 내리막 — 수레 탄 사람은 브레이크'. 화살표가 갈수록 굵어진다." w=2
enemy CR-095 35 9 cond="DG_U04 == 0"
enemy CR-095 82 8 cond="DG_U04 == 0"
